import ast,hashlib,json
from pathlib import Path
runtime=json.load(open('/tmp/r001.json'));p=json.load(open('proposal.json'))
seen=set()
def validate(value,schema,path='"'$'"'):
 seen.update(schema)
 typ=schema.get('type')
 classes={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int,'number':(int,float)}
 if typ:
  assert isinstance(value,classes[typ]),(path,'type',typ,type(value).__name__)
  if typ in ('number','integer'):assert not isinstance(value,bool)
 if 'const' in schema:assert value==schema['const'],(path,'const')
 if 'enum' in schema:assert value in schema['enum'],(path,'enum')
 if 'minLength' in schema:assert len(value)>=schema['minLength'],(path,'minLength')
 if 'minItems' in schema:assert len(value)>=schema['minItems'],(path,'minItems')
 if isinstance(value,dict):
  assert all(k in value for k in schema.get('required',[])),(path,'required')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False:assert set(value)<=set(props),(path,'extra',set(value)-set(props))
  for k,v in value.items():
   if k in props:validate(v,props[k],path+'.'+k)
 if isinstance(value,list) and 'items' in schema:
  for i,v in enumerate(value):validate(v,schema['items'],path+f'[{i}]')
validate(p['study'],runtime['study_schema'])
assert seen<={'"'$schema'"','title','type','additionalProperties','required','properties','minLength','minItems','items','enum','const'}
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
anc=ast.parse(Path('history_g1_r0041_match_swap_task.py').read_text());ac=next(n for n in anc.body if isinstance(n,ast.ClassDef)); am={n.name:ast.dump(n) for n in ac.body if isinstance(n,ast.FunctionDef)}
baseconfig=next(ast.literal_eval(n.value) for n in anc.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
frozen={'epochs','batch_size','train_seed','seed','history_limit','learning_rate','dense_learning_rate','sparse_learning_rate','num_workers','precision','gradient_clip'}
print('Study schema, parent, evidence references and four-variant contract: PASS')
body_hashes=[]
for v in p['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 txt=Path(v['file']).read_text();tree=ast.parse(txt);compile(txt,v['file'],'exec')
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==v['config'] and not (frozen & set(config))
 assert set(config)==set(baseconfig)|{'match_basis_initialization'}
 assert all(config[k]==baseconfig[k] for k in baseconfig if k not in ('residual_routing','match_action_basis'))
 assert hashlib.sha256(txt.encode()).hexdigest() in v['note']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef)); m={n.name:ast.dump(n) for n in cls.body if isinstance(n,ast.FunctionDef)}
 assert set(m)==set(am)|{'_transport_match_input_weights'}
 assert all(m[k]==am[k] for k in am if k"'!='"'__init__')
 rest=[n for n in tree.body if not(isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))]
 body_hashes.append(hashlib.sha256(ast.dump(ast.Module(body=rest,type_ignores=[])).encode()).hexdigest())
 print(v['name'],v['role'],v['file'],'CONFIG/source hash/syntax/frozen-method parity PASS')
assert len(set(body_hashes))==1
# Check offset accounting independently from row-major residual feature layout.
for context_width in (0,16,160):
 for fields in (1,6,9):
  for dim in (1,16):
   key=fields*dim;value=key+dim;prefix=context_width+key+value+3
   labels=['prefix']*prefix
   for row in range(5):labels += [('item',row)]*key + [('action',row)]*dim
   first=prefix+key;last=first+4*value
   assert labels[first:first+dim]==[('action',0)]*dim
   assert labels[last:last+dim]==[('action',4)]*dim
   assert len(set(range(first,first+dim))&set(range(last,last+dim)))==0
print('Independent row-major column indexing for varying field widths: PASS')
print('All four module bodies identical outside CONFIG: PASS')
print('Pending host tensor checks and scores explicitly documented. No experiment executed.')
print('proposal.json SHA256',hashlib.sha256(Path('proposal.json').read_bytes()).hexdigest())
PY"

